packed=packed:gsub("%s+","")
local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local letters={}
for i=1,#alphabet do letters[alphabet:byte(i)]=i-1 end
local dict,nextCode,prior={},258,nil
local function reset()
  dict={}
  for i=0,255 do dict[i]=string.char(i) end
  nextCode=258
  prior=nil
end
reset()
local fragments={}
local ended=false
for i=1,#packed,2 do
  local a,b=letters[packed:byte(i)],letters[packed:byte(i+1)]
  if a==nil or b==nil then error("Packed controller data invalid",0) end
  local code=a*64+b
  if code==256 then
    reset()
  elseif code==257 then
    ended=true
    break
  else
    local value=dict[code]
    if not value then
      if code==nextCode and prior then
        value=prior..prior:sub(1,1)
      else
        error("Packed controller LZW code invalid at "..i,0)
      end
    end
    fragments[#fragments+1]=value
    if prior and nextCode<4096 then
      dict[nextCode]=prior..value:sub(1,1)
      nextCode=nextCode+1
    end
    prior=value
  end
end
if not ended then error("Packed controller missing end code",0) end
local source=table.concat(fragments)
if #source~=96907 then error("Packed controller length mismatch",0) end
local hash=0
for i=1,#source do hash=(hash*33+source:byte(i))%4294967296 end
if hash~=1993665189 then error("Packed controller checksum mismatch",0) end
if rawget(_G,"CC_MEKANISM_PAYLOAD_TEST")==true then return source end
local program,err=load(source,"@/cc-mekanism/controller.lua","t",_ENV)
if not program then error("Packed controller syntax error: "..tostring(err),0) end
return program()
